    `seo`, `seo_title`, `seo_desc`, `seo_keyword`, `updated_at`, `created_at`
  ) VALUES (
    'comic-nhiem-vu-hongsil', 'NHIỆM VỤ HONGSIL', 'nhiem-vu-hongsil', '[\"홍실퀘스트 / Red Thread of Fate Quest / Red Thread Quest\"]', 'https://tachserver.site/cdn3/uploads/minh_hoa/nhiem-vu-hongsil-1760203225.jpg', 'https://tachserver.site/cdn3/uploads/minh_hoa/nhiem-vu-hongsil-1760203225.jpg',
    '[\"Leesin Team\"]', 'Đang tiến hành', '[\"Tình Yêu\",\"Manhwa\",\"Đam Mỹ\",\"Học Đường\",\"Hài Hước\",\"Boy Love\",\"Drama\",\"18+\"]', 'Lee Yeon, một sinh viên đại học chuyên ngành Luật, một ngày nọ tình cờ gặp Kihoon-tiền bối từng thầm thương trộm nhớ cậu hồi trung học. Trong một chuyến đi mà họ cùng nhau thực hiện theo gợi ý của Kihoon, cả hai bất ngờ nhận được một nhiệm vụ kỳ lạ: \"Nhiệm vụ Tơ hồng Định mệnh\". \"Nhiệm vụ Hongsil, Vòng 1: Hôn lên má 5 lần!\" Nhưng khi Yeon, người hoài nghi về những ý tưởng như \"định mệnh dành cho nhau\", bị cuốn vào câu chuyện dân gian xoay quanh \"Sợi tơ hồng định mệnh\", mối quan hệ của họ bắt đầu thay đổi theo cách mà không ai trong số họ có thể lường trước được...! Truyện được đăng tải duy nhất tại Leesincomic.com!!!', 'team-lessin-comic', 'Lessin Comic',
    13396, 533, 2926, 13298,
    533, 2926, 13298,
    1595, 7, 4.9, 110,
    0, 1, 0,
    '{\"focusKeyword\":\"NHIỆM VỤ HONGSIL\",\"metaTitle\":\"NHIỆM VỤ HONGSIL | Leesin Comic\",\"metaDesc\":\"Lee Yeon, một sinh viên đại học chuyên ngành Luật, một ngày nọ tình cờ gặp Kihoon-tiền bối từng thầm thương trộm nhớ cậu hồi trung học. Trong một chuy\",\"canonicalUrl\":\"https://leesincomic.com/truyen-tranh/nhiem-vu-hongsil.html\",\"score\":92,\"schemaType\":\"ComicBook\",\"ogImage\":\"https://tachserver.site/cdn3/uploads/minh_hoa/nhiem-vu-hongsil-1760203225.jpg\"}', 'NHIỆM VỤ HONGSIL | Leesin Comic', 'Lee Yeon, một sinh viên đại học chuyên ngành Luật, một ngày nọ tình cờ gặp Kihoon-tiền bối từng thầm thương trộm nhớ cậu hồi trung học. Trong một chuy', 'NHIỆM VỤ HONGSIL', '2026-09-27T04:57:00.000Z', '2026-09-27T04:57:00.000Z'
  ) ON DUPLICATE KEY UPDATE
