    `seo`, `seo_title`, `seo_desc`, `seo_keyword`, `updated_at`, `created_at`
  ) VALUES (
    'comic-thanh-ca-mua-ha', 'THÁNH CA MÙA HẠ', 'thanh-ca-mua-ha', '[\"여름의 캐럴 - A Midsummer\'s Carol\"]', 'https://tachserver.site/cdn3/uploads/minh_hoa/thanh-ca-mua-ha-1786279272.jpg', 'https://tachserver.site/cdn3/uploads/minh_hoa/thanh-ca-mua-ha-1786279272.jpg',
    '[\"Leesin Team\"]', 'Đang tiến hành', '[\"Truyện Màu\",\"Kịch Tính\",\"Lãng Mạn\",\"Tình Cảm\",\"Tình Yêu\",\"Manhwa\",\"Drama\",\"18+\"]', 'Sau những thất bại trong tình yêu lẫn công việc, Do Kyung quay về với sự tĩnh lặng nơi vùng quê Mooyung. Ở tiệm tạp hoá cũ của mẹ, cô tình cờ gặp được Doh Joon, nam diễn viên hàng đầu với đôi mắt sâu thẳm như màn đêm. Từ một lời đề nghị táo bạo, mối quan hệ của họ dần trở nên rắc rối hơn: một mối tình thoáng qua giữa mùa hạ của một người phụ nữ e dè trước tình yêu và một người đàn ông khao khát tình yêu lâu bền. Khi những ngày hè càng trở nên oi bức và những đêm càng thêm gần gũi, Do Kyung vẫn cho rằng mối quan hệ này sẽ chỉ gói gọn trong mùa hạ, chỉ là một khoảnh khắc ngắn ngủi. Nhưng với Doh Joon, anh đã bắt đầu mơ về những điều sẽ còn tiếp diễn, kể cả khi mùa hạ đã qua đi.', 'team-la-muse-team', 'Là Muse Team',
    7967, 528, 1356, 7536,
    528, 1356, 7536,
    904, 14, 4.9, 62,
    0, 0, 0,
    '{\"focusKeyword\":\"THÁNH CA MÙA HẠ\",\"metaTitle\":\"THÁNH CA MÙA HẠ | Leesin Comic\",\"metaDesc\":\"Sau những thất bại trong tình yêu lẫn công việc, Do Kyung quay về với sự tĩnh lặng nơi vùng quê Mooyung. Ở tiệm tạp hoá cũ của mẹ, cô tình cờ gặp được\",\"canonicalUrl\":\"https://leesincomic.com/truyen-tranh/thanh-ca-mua-ha.html\",\"score\":92,\"schemaType\":\"ComicBook\",\"ogImage\":\"https://tachserver.site/cdn3/uploads/minh_hoa/thanh-ca-mua-ha-1786279272.jpg\"}', 'THÁNH CA MÙA HẠ | Leesin Comic', 'Sau những thất bại trong tình yêu lẫn công việc, Do Kyung quay về với sự tĩnh lặng nơi vùng quê Mooyung. Ở tiệm tạp hoá cũ của mẹ, cô tình cờ gặp được', 'THÁNH CA MÙA HẠ', '2026-09-22T12:00:00.000Z', '2026-09-22T12:00:00.000Z'
