  ) VALUES (
    'comic-nu-phap-y-than-yeu-cua-toi-pheromone', 'Nữ Pháp Y Thân Yêu Của Tôi - Pheromone', 'nu-phap-y-than-yeu-cua-toi-pheromone', '[\"我亲爱的法医小姐\"]', 'https://tachserver.site/cdn3/uploads/minh_hoa/nu-phap-y-than-yeu-cua-toi--pheromone-1787139205.jpg', 'https://tachserver.site/cdn3/uploads/minh_hoa/nu-phap-y-than-yeu-cua-toi--pheromone-1787139205.jpg',
    '[\"Leesin Team\"]', 'Đang tiến hành', '[\"GirlLove\",\"Bách Hợp\",\"Yuri\",\"Manhua\",\"Girl Love\"]', 'Miss Forensics - \\\\\\\"Nữ bác sĩ pháp y lạnh lùng kiêu ngạo\\\\\\\" Lâm Yêm x \\\\\\\"Nữ cảnh sát chính trực nghiêm nghị\\\\\\\" Tống Dư Hàng. Từ hai người như nước với lửa đến gặp gỡ, quen biết nhau và thấu hiểu nhau. Họ cùng nhau trải qua một đường nhân sinh chứng kiến bao con người nhỏ bé ngoài kia đang vật vã với cuộc sống: một cô gái nhỏ làm việc chăm chỉ nhưng lại chết một cách oan uổng, một người mẹ già côi cút ở trong núi sâu chờ đợi đứa con của tội phạm của mình trở về, một người cảnh sát nhỏ bé nhút nhát nhưng đã hy sinh thân mình để đối mặt với những họng súng của đối phương... Họ đứng lên vì quyền lợi của những người đang sống, lên tiếng cho những người đã chết và nhất định tìm ra dù sự thật dù đã bị che giấu bao nhiêu năm...', 'team-pheromone', 'Pheromone',
    6155, 408, 1341, 5832,
    408, 1341, 5832,
    699, 222, 4.9, 48,
    0, 0, 0,
    '{\"focusKeyword\":\"Nữ Pháp Y Thân Yêu Của Tôi - Pheromone\",\"metaTitle\":\"Nữ Pháp Y Thân Yêu Của Tôi - Pheromone | Leesin Comic\",\"metaDesc\":\"Miss Forensics - \\\\\\\\\\\\\\\"Nữ bác sĩ pháp y lạnh lùng kiêu ngạo\\\\\\\\\\\\\\\" Lâm Yêm x \\\\\\\\\\\\\\\"Nữ cảnh sát chính trực nghiêm nghị\\\\\\\\\\\\\\\" Tống Dư Hàng. Từ hai người như nước\",\"canonicalUrl\":\"https://leesincomic.com/truyen-tranh/nu-phap-y-than-yeu-cua-toi--pheromone.html\",\"score\":92,\"schemaType\":\"ComicBook\",\"ogImage\":\"https://tachserver.site/cdn3/uploads/minh_hoa/nu-phap-y-than-yeu-cua-toi--pheromone-1787139205.jpg\"}', 'Nữ Pháp Y Thân Yêu Của Tôi - Pheromone | Leesin Comic', 'Miss Forensics - \\\\\\\"Nữ bác sĩ pháp y lạnh lùng kiêu ngạo\\\\\\\" Lâm Yêm x \\\\\\\"Nữ cảnh sát chính trực nghiêm nghị\\\\\\\" Tống Dư Hàng. Từ hai người như nước', 'Nữ Pháp Y Thân Yêu Của Tôi - Pheromone', '2026-09-18T12:00:00.000Z', '2026-09-18T12:00:00.000Z'
