    `seo`, `seo_title`, `seo_desc`, `seo_keyword`, `updated_at`, `created_at`
  ) VALUES (
    'comic-em-gai-benh-kieu-muoi-muoi-chi-muon-toi-bat-nat-em-ay-pheromone', 'Em Gái Bệnh Kiều Muội Muội Chỉ Muốn Tôi Bắt Nạt Em Ấy - Pheromone', 'em-gai-benh-kieu-muoi-muoi-chi-muon-toi-bat-nat-em-ay-pheromone', '[\"病娇妹妹只想让我欺负她\"]', 'https://tachserver.site/cdn3/uploads/minh_hoa/em-gai-benh-kieu-muoi-muoi-chi-muon-toi-bat-nat-em-ay--pheromone-1787144215.jpg', 'https://tachserver.site/cdn3/uploads/minh_hoa/em-gai-benh-kieu-muoi-muoi-chi-muon-toi-bat-nat-em-ay--pheromone-1787144215.jpg',
    '[\"Leesin Team\"]', 'Đang tiến hành', '[\"GirlLove\",\"Bách Hợp\",\"Yuri\",\"Manhua\",\"Girl Love\"]', 'Thân là tiểu thuyết gia nữ chủ, cực kỳ chán ghét trà xanh kỹ nữ bạch liên hoa, cố ý viết vào trong tiểu thuyết xuất hiện một nhân vậtkhông ngừng ngược đãi nữ chính! Lại không nghĩ rằng chính mình lại bị xuyên không vào tiểu thuyết đấy, thế ta đây cần phải tự mình động thủ vào bạch liên hoa để xả giận! Nhưng bị sắc đẹp của nữ chính mê hoặc, cô không những không thể tấn công tiểu bạch hoa xinh đẹp này mà còn dần dần trở thành hộ hoa sứ giả bên cạnh nữ chính…… Ngay tại thời điểm cô nghĩ về phần tâm ý lệch lạc này của mình mà thấp thỏm, nữ chính luôn nhu nhược kia một tay đẩy nam chính ra xa ba mét, bướng bỉnh hướng Cố Hình tỏ tình! Cái gì? Hóa ra tôi mới là người được bảo vệ sao?!', 'team-pheromone', 'Pheromone',
    4711, 152, 866, 4330,
    152, 866, 4330,
    519, 156, 4.9, 36,
    0, 0, 0,
    '{\"focusKeyword\":\"Em Gái Bệnh Kiều Muội Muội Chỉ Muốn Tôi Bắt Nạt Em Ấy - Pheromone\",\"metaTitle\":\"Em Gái Bệnh Kiều Muội Muội Chỉ Muốn Tôi Bắt Nạt Em Ấy - Pheromone | Leesin Comic\",\"metaDesc\":\"Thân là tiểu thuyết gia nữ chủ, cực kỳ chán ghét trà xanh kỹ nữ bạch liên hoa, cố ý viết vào trong tiểu thuyết xuất hiện một nhân vậtkhông ngừng ngược\",\"canonicalUrl\":\"https://leesincomic.com/truyen-tranh/em-gai-benh-kieu-muoi-muoi-chi-muon-toi-bat-nat-em-ay--pheromone.html\",\"score\":92,\"schemaType\":\"ComicBook\",\"ogImage\":\"https://tachserver.site/cdn3/uploads/minh_hoa/em-gai-benh-kieu-muoi-muoi-chi-muon-toi-bat-nat-em-ay--pheromone-1787144215.jpg\"}', 'Em Gái Bệnh Kiều Muội Muội Chỉ Muốn Tôi Bắt Nạt Em Ấy - Pheromone | Leesin Comic', 'Thân là tiểu thuyết gia nữ chủ, cực kỳ chán ghét trà xanh kỹ nữ bạch liên hoa, cố ý viết vào trong tiểu thuyết xuất hiện một nhân vậtkhông ngừng ngược', 'Em Gái Bệnh Kiều Muội Muội Chỉ Muốn Tôi Bắt Nạt Em Ấy - Pheromone', '2026-09-18T12:00:00.000Z', '2026-09-18T12:00:00.000Z'
