  ) VALUES (
    'comic-18-nguoi-tinh-trong-bong-toi', '[18+] Người Tình Trong Bóng Tối', '18-nguoi-tinh-trong-bong-toi', '[\"The Secret Concubine\"]', 'https://tachserver.site/cdn3/uploads/minh_hoa/nguoi-tinh-trong-bong-toi--1789138776.png', 'https://tachserver.site/cdn3/uploads/minh_hoa/nguoi-tinh-trong-bong-toi--1789138776.png',
    '[\"Leesin Team\"]', 'Đang tiến hành', '[\"Truyện Màu\",\"Lãng Mạn\",\"Tình Cảm\",\"Tình Yêu\",\"Manhwa\",\"Drama\",\"18+\"]', 'Giữa màn đêm đen kịt, chỉ được soi sáng bởi ánh trăng nhợt nhạt, Soon Jeong buộc phải trao thân mình cho thiếu gia Jin Woo. Bị ép phải thay thế vị tiểu thư yếu ớt, cô hầu trẻ trở thành người tình bí mật hứng chịu những ham muốn đen tối và mất kiểm soát của chủ nhân. Jin Woo lạnh lùng, kiêu ngạo và tàn nhẫn, đối xử với Soon Jeong như một công cụ để giải tỏa nhu cầu của mình chứ không coi cô như một con người. Hắn cảnh cáo cô tuyệt đối không được mong chờ tình cảm hay sự dịu dàng từ hắn. Thế nhưng, khi sự áp đặt lạnh lùng và những ham muốn mãnh liệt của hắn liên tục đẩy cô đến giới hạn chịu đựng, Soon Jeong dần bị trói buộc vào một chủ nhân mà hơi thở lạnh lẽo cùng mối quan hệ đầy căng thẳng ấy có thể hủy hoại cô hoàn toàn.', 'team-vuon-hoa-mat-troi', 'Vườn Hoa Mặt Trời',
    384, 15, 75, 333,
    15, 75, 333,
    50, 1, 4.9, 15,
    0, 0, 0,
    '{\"focusKeyword\":\"[18+] Người Tình Trong Bóng Tối\",\"metaTitle\":\"[18+] Người Tình Trong Bóng Tối | Leesin Comic\",\"metaDesc\":\"Giữa màn đêm đen kịt, chỉ được soi sáng bởi ánh trăng nhợt nhạt, Soon Jeong buộc phải trao thân mình cho thiếu gia Jin Woo. Bị ép phải thay thế vị tiể\",\"canonicalUrl\":\"https://leesincomic.com/truyen-tranh/18+-nguoi-tinh-trong-bong-toi.html\",\"score\":92,\"schemaType\":\"ComicBook\",\"ogImage\":\"https://tachserver.site/cdn3/uploads/minh_hoa/nguoi-tinh-trong-bong-toi--1789138776.png\"}', '[18+] Người Tình Trong Bóng Tối | Leesin Comic', 'Giữa màn đêm đen kịt, chỉ được soi sáng bởi ánh trăng nhợt nhạt, Soon Jeong buộc phải trao thân mình cho thiếu gia Jin Woo. Bị ép phải thay thế vị tiể', '[18+] Người Tình Trong Bóng Tối', '2026-09-16T05:00:00.000Z', '2026-09-16T05:00:00.000Z'
