  ) VALUES (
    'comic-tien-vong', 'Tiễn Vong', 'tien-vong', '[\"[성비단 음란침공] 소란스러운 한밤에\"]', 'https://tachserver.site/cdn3/uploads/minh_hoa/tien-vong-1786381154.png', 'https://tachserver.site/cdn3/uploads/minh_hoa/tien-vong-1786381154.png',
    '[\"Leesin Team\"]', 'Đang tiến hành', '[\"Truyện Màu\",\"Kịch Tính\",\"Tình Cảm\",\"BoyLove\",\"Yaoi\",\"Tình Yêu\",\"Đã Full\",\"Manhwa\",\"Đam Mỹ\",\"Hài Hước\",\"Drama\",\"Horror\",\"18+\",\"Oneshot\"]', 'Jong-eon, một chàng trai có khả năng nhìn thấy ma từ nhỏ khiến cuộc sống luôn u ám. Mọi thứ thay đổi khi cậu làm bài tập nhóm với Hyeseong - một đàn em khóa dưới có khả năng đặc biệt như một \"vũ khí đuổi ma\" di động. Để được yên ổn, Jong-eon bám theo Hyeseong nhưng khi bị phát hiện, cậu đã cuống cuồng nói dối rằng mình... yêu thầm đối phương.', 'team-lessin-comic', 'Lessin Comic',
    5039, 301, 1155, 5021,
    301, 1155, 5021,
    602, 2, 4.9, 41,
    0, 0, 0,
    '{\"focusKeyword\":\"Tiễn Vong\",\"metaTitle\":\"Tiễn Vong | Leesin Comic\",\"metaDesc\":\"Jong-eon, một chàng trai có khả năng nhìn thấy ma từ nhỏ khiến cuộc sống luôn u ám. Mọi thứ thay đổi khi cậu làm bài tập nhóm với Hyeseong - một đàn e\",\"canonicalUrl\":\"https://leesincomic.com/truyen-tranh/tien-vong.html\",\"score\":92,\"schemaType\":\"ComicBook\",\"ogImage\":\"https://tachserver.site/cdn3/uploads/minh_hoa/tien-vong-1786381154.png\"}', 'Tiễn Vong | Leesin Comic', 'Jong-eon, một chàng trai có khả năng nhìn thấy ma từ nhỏ khiến cuộc sống luôn u ám. Mọi thứ thay đổi khi cậu làm bài tập nhóm với Hyeseong - một đàn e', 'Tiễn Vong', '2026-08-12T05:00:00.000Z', '2026-08-12T05:00:00.000Z'
