    `seo`, `seo_title`, `seo_desc`, `seo_keyword`, `updated_at`, `created_at`
  ) VALUES (
    'comic-thanh-nu-uot-at', 'Thánh Nữ Ướt Át', 'thanh-nu-uot-at', '[\"성녀의 꽃잎은 젖어든다\"]', 'https://tachserver.site/cdn3/uploads/minh_hoa/thanh-nu-uot-at-1783259730.jpg', 'https://tachserver.site/cdn3/uploads/minh_hoa/thanh-nu-uot-at-1783259730.jpg',
    '[\"Leesin Team\"]', 'Đang tiến hành', '[\"Truyện Màu\",\"Lãng Mạn\",\"Tình Cảm\",\"Harem\",\"Manhwa\",\"18+\"]', '\"Hỡi Thánh nữ, để ta ban cho nàng những khoái cảm mà cả đời này sẽ không bao giờ quên.\" Khoảnh khắc tôi ước được tự do tận hưởng bên những người đàn ông tuấn mỹ, tôi bỗng phát hiện mình nhập vào Agnes – vị Thánh nữ sa ngã trong một tiểu thuyết 19+ đầy kịch tính. Một vị Đại Tư tế khắt khe “huấn luyện” nàng mỗi ngày dưới danh nghĩa “giáo dục”, Một vị Hoàng đế mang trong mình huyết thống rồng, lấy lý do “trấn áp long huyết” mà tìm đến nàng, Và một Chủ tháp bí ẩn luôn xuất hiện mỗi đêm để thử nghiệm những ma pháp quái dị. Nếu không thể tránh, thì hãy học cách tận hưởng. Những trải nghiệm nồng nhiệt, những thử thách khó cưỡng, và một cuộc đời cuồng nhiệt của Thánh nữ đã rơi vào vòng xoáy cám dỗ.', 'team-bach-duong-team', 'Bạch Dương Team',
    5583, 361, 1388, 5553,
    361, 1388, 5553,
    666, 4, 4.9, 46,
    0, 0, 0,
    '{\"focusKeyword\":\"Thánh Nữ Ướt Át\",\"metaTitle\":\"Thánh Nữ Ướt Át | Leesin Comic\",\"metaDesc\":\"\\\"Hỡi Thánh nữ, để ta ban cho nàng những khoái cảm mà cả đời này sẽ không bao giờ quên.\\\" Khoảnh khắc tôi ước được tự do tận hưởng bên những người đàn ô\",\"canonicalUrl\":\"https://leesincomic.com/truyen-tranh/thanh-nu-uot-at.html\",\"score\":92,\"schemaType\":\"ComicBook\",\"ogImage\":\"https://tachserver.site/cdn3/uploads/minh_hoa/thanh-nu-uot-at-1783259730.jpg\"}', 'Thánh Nữ Ướt Át | Leesin Comic', '\"Hỡi Thánh nữ, để ta ban cho nàng những khoái cảm mà cả đời này sẽ không bao giờ quên.\" Khoảnh khắc tôi ước được tự do tận hưởng bên những người đàn ô', 'Thánh Nữ Ướt Át', '2026-07-10T05:00:00.000Z', '2026-07-10T05:00:00.000Z'
