  ) VALUES (
    'comic-19-hen-uoc-dau-ngon-tay', '[19+] Hẹn Ước Đầu Ngón Tay', '19-hen-uoc-dau-ngon-tay', '[]', 'https://tachserver.site/cdn3/uploads/minh_hoa/hen-uoc-dau-ngon-tay-1785471582.jpg', 'https://tachserver.site/cdn3/uploads/minh_hoa/hen-uoc-dau-ngon-tay-1785471582.jpg',
    '[\"Leesin Team\"]', 'Đang tiến hành', '[\"Truyện Màu\",\"GirlLove\",\"Bách Hợp\",\"Lãng Mạn\",\"Tình Cảm\",\"Yuri\",\"Tình Yêu\",\"Manhwa\",\"Học Đường\",\"Girl Love\",\"Drama\",\"18+\"]', 'Eva và Hallie đã từng hứa sẽ mãi là bạn thân của nhau. Nhưng khi năm cuối đại học dần trôi qua, mọi thứ cũng bắt đầu thay đổi. Một người mới xuất hiện trong cuộc sống của họ, và những điều từng quen thuộc giờ đây lại trở nên mơ hồ. Khi khoảng cách ngày một lớn dần và sự thật cứ lặng im bị che giấu, chỉ còn một câu hỏi ở lại: Liệu họ sẽ vẫn là những người bạn như đã từng hứa… hay sẽ trở thành điều mà cả hai chưa bao giờ nghĩ đến?', 'team-lavibit-windroom-gl', 'Lavibit Windroom GL',
    44206, 2413, 9652, 43873,
    2413, 9652, 43873,
    5264, 223, 4.9, 365,
    1, 1, 0,
    '{\"focusKeyword\":\"[19+] Hẹn Ước Đầu Ngón Tay\",\"metaTitle\":\"[19+] Hẹn Ước Đầu Ngón Tay | Leesin Comic\",\"metaDesc\":\"Eva và Hallie đã từng hứa sẽ mãi là bạn thân của nhau. Nhưng khi năm cuối đại học dần trôi qua, mọi thứ cũng bắt đầu thay đổi. Một người mới xuất hiện\",\"canonicalUrl\":\"https://leesincomic.com/truyen-tranh/19+-hen-uoc-dau-ngon-tay.html\",\"score\":92,\"schemaType\":\"ComicBook\",\"ogImage\":\"https://tachserver.site/cdn3/uploads/minh_hoa/hen-uoc-dau-ngon-tay-1785471582.jpg\"}', '[19+] Hẹn Ước Đầu Ngón Tay | Leesin Comic', 'Eva và Hallie đã từng hứa sẽ mãi là bạn thân của nhau. Nhưng khi năm cuối đại học dần trôi qua, mọi thứ cũng bắt đầu thay đổi. Một người mới xuất hiện', '[19+] Hẹn Ước Đầu Ngón Tay', '2026-05-25T05:00:00.000Z', '2026-05-25T05:00:00.000Z'
