INSERT INTO `comics` (
    `id`, `title`, `slug`, `other_names`, `cover_image`, `banner_image`,
    `authors`, `status`, `genres`, `summary`, `team_id`, `team_name`,
    `views`, `views_day`, `views_week`, `views_month`,
    `daily_views`, `weekly_views`, `monthly_views`,
    `likes`, `follows`, `rating`, `rating_count`,
    `is_hot`, `is_trending`, `is_vip_only`,
    `seo`, `seo_title`, `seo_desc`, `seo_keyword`, `updated_at`, `created_at`
  ) VALUES (
    'comic-play-room', 'Play Room', 'play-room', '[\"Play Room; 플레이룸\"]', 'https://tachserver.site/cdn3/uploads/minh_hoa/play-room-1785415069.jpg', 'https://tachserver.site/cdn3/uploads/minh_hoa/play-room-1785415069.jpg',
    '[\"Leesin Team\"]', 'Đang tiến hành', '[\"Tình Yêu\",\"Manhwa\",\"Đam Mỹ\",\"Boy Love\",\"Drama\",\"18+\"]', 'Woojun, người đã lớn lên trong cảnh nghèo khó và từng làm qua đủ mọi công việc, vội vã trở về quê nhà sau khi nghe tin mẹ đơn thân của mình gặp tai nạn giao thông. Tuy nhiên, anh hoàn toàn choáng ngợp trước những hóa đơn viện phí và chi phí sinh hoạt vượt xa khả năng của mình. Rồi một ngày nọ, để kiếm sống, anh tình cờ có được một buổi phỏng vấn tại một khách sạn sang trọng nằm sâu trong vùng nông thôn và phát hiện ra sự tồn tại của một căn phòng VIP dành riêng cho giới thượng lưu. Hơn nữa, chủ khách sạn, Kang Rahan, đưa ra cho anh một đề nghị bất ngờ... “Thật ra điều tôi muốn nhờ anh không chỉ là công việc ở khách sạn.” “Vậy thì...?” “Là bạn tình của tôi. Nói chính xác hơn vừa là bạn tình, vừa là nhân viên. Quyết định là ở anh, Woojun.”', 'team-lessin-comic', 'Lessin Comic',
    14349, 860, 3153, 14333,
    860, 3153, 14333,
    1719, 1, 4.9, 119,
    0, 1, 0,
    '{\"focusKeyword\":\"Play Room\",\"metaTitle\":\"Play Room | Leesin Comic\",\"metaDesc\":\"Woojun, người đã lớn lên trong cảnh nghèo khó và từng làm qua đủ mọi công việc, vội vã trở về quê nhà sau khi nghe tin mẹ đơn thân của mình gặp tai nạ\",\"canonicalUrl\":\"https://leesincomic.com/truyen-tranh/play-room.html\",\"score\":92,\"schemaType\":\"ComicBook\",\"ogImage\":\"https://tachserver.site/cdn3/uploads/minh_hoa/play-room-1785415069.jpg\"}', 'Play Room | Leesin Comic', 'Woojun, người đã lớn lên trong cảnh nghèo khó và từng làm qua đủ mọi công việc, vội vã trở về quê nhà sau khi nghe tin mẹ đơn thân của mình gặp tai nạ', 'Play Room', '2026-05-03T05:00:00.000Z', '2026-05-03T05:00:00.000Z'
